import { Link, useNavigate } from "react-router-dom";
import axios from "axios";
import toast from "react-hot-toast";

function Add_delete() {
  const initialStudentState = {
    name: "",
    class: "",
    roll: "",
    gender: "",
  };
  const [student, setStudent] = useState(initialStudentState);
  const navigate = useNavigate();
  const API_URL = "http://localhost:8001/api/user"; // Endpoint for creating a user/student

  // Handle input field changes
  const inputHandler = (e) => {
    const { name, value } = e.target;
    // Update the correct state object (student)
    setStudent({ ...student, [name]: value });
  };

  // Handle form submission
  const submitForm = async (e) => {
    e.preventDefault();
    await axios
      .post(API_URL, student) // Send the student data to the API
      .then((response) => {
        toast.success(response.data.message || "Student added successfully!", { position: "top-right" });
        // You might want to navigate to the student list or teacher dashboard
        navigate("/Teacherdashboard"); 
      })
      .catch((error) => {
        console.error("❌ Error adding student:", error);
        // Display error message from server if available, otherwise a generic one
        const errorMessage = error.response?.data?.message || "Failed to add student. Check server logs.";
        toast.error(errorMessage, { position: "top-right" });
      });
  };

  return (
    // Component name in className changed for clarity, adjust CSS as needed
    <div className="addStudent"> 
      {/* Assuming /Teacherdashboard is where the teacher goes back to */}
      <Link to="/Teacherdashboard" type="button" className="btn btn-secondary">
        <i className="fa-solid fa-backward"></i> Back
      </Link>

      <h3>Add New Student</h3>
      <form className="addStudentForm" onSubmit={submitForm}>
        
        {/* Input for Name */}
        <div className="inputGroup">
          <label htmlFor="name">Name:</label>
          <input
            type="text"
            id="name"
            onChange={inputHandler}
            name="name"
            autoComplete="off"
            placeholder="Enter student's name"
            required // Added required
          />
        </div>

        {/* Select for Class */}
        <div className="inputGroup">
          <label htmlFor="class">Class:</label>
          <select 
            id="class" 
            name='class' 
            onChange={inputHandler}
            value={student.class}
            required // Added required
          >
            <option value="">-- Select Class --</option>
            <option value="10">10</option>
            <option value="9">9</option>
            <option value="8">8</option>
            <option value="7">7</option>
            {/* Make sure these values match what your backend expects */}
          </select>
        </div>

        {/* Input for Roll */}
        <div className="inputGroup">
          <label htmlFor="roll">Roll No:</label>
          <input
            type="text"
            id="roll"
            onChange={inputHandler}
            name="roll"
            autoComplete="off"
            placeholder="Enter roll number"
            required // Added required
          />
        </div>

        {/* Select for Gender */}
        <div className="inputGroup">
          <label htmlFor="gender">Gender:</label>
          <select 
            id="gender" 
            name='gender' 
            onChange={inputHandler}
            value={student.gender}
            required // Added required
          >
            <option value="">-- Select Gender --</option>
            <option value="male">Male</option>
            <option value="female">Female</option>
            <option value="other">Other</option>
            {/* Make sure these values match what your backend expects */}
          </select>
        </div>

        <div className="inputGroup">
          <button type="submit" className="btn btn-primary">
            Submit
          </button>
        </div>
      </form>
    </div>
  );
};
export default Add_delete;
